public class SuperFormationHeroMarch
{
    private string _heroId;

    public string heroId
    {
        get => _heroId;
        set
        {
            if (string.IsNullOrEmpty(value))
            {
                maxMarch = 0;
                heroLv = 0;
                starLv = 0;
            }

            _heroId = value;
        }
    }

    public int heroLv; //英雄等级
    public int starLv; //英雄等级
    public int maxMarch;
    public CCDictionary heroDict;

    public SuperFormationHeroMarch()
    {
    }

    public SuperFormationHeroMarch(string heroId, int heroLv, int starLv, CCDictionary dict = null)
    {
        this.heroId = heroId;
        this.heroLv = heroLv;
        this.starLv = starLv;
        this.heroDict = dict;
    }
}

public class SuperFormationSoldierMarch
{
    public string armyType;
    public string armyId;
    private int _count;

    public int count
    {
        get { return _count; }
        set
        {
            _count = value;
            LogCommon.LogError("改变士兵值" + value);
        }
    } // 兵种的数量

    public CCDictionary info_dict;

    public SuperFormationSoldierMarch(string armyId, int count, CCDictionary dict = null)
    {
        this.armyId = armyId;
        this.count = count;
        this.info_dict = dict;
    }

    private Arms _armsInfo;

    public Arms GetArmsInfo()
    {
        if (_armsInfo == null || _armsInfo.id != armyId)
            _armsInfo = DataAtlasManager.Instance.GetDataWithTypeById<Arms>(armyId);
        return _armsInfo;
    }
}

