public string GetFormMsg_log()
{
    var sb = new System.Text.StringBuilder();
    sb.Append(GetFormMsg());

    var heros = getHerosList();
    sb.Append($" | heros({heros.Count}):");
    for (int i = 0; i < heros.Count; i++)
    {
        var h = heros[i];
        sb.Append($" [{i}]{h.heroId} lv{h.heroLv} star{h.starLv} march{h.maxMarch}");
    }

    var soldiers = getSoldierList();
    sb.Append($" | soldiers({soldiers.Count}):");
    for (int i = 0; i < soldiers.Count; i++)
    {
        var s = soldiers[i];
        sb.Append($" [{i}]{s.armyId}({s.armyType})x{s.count}");
    }

    return sb.ToString();
}

