        {
            m_maxNum = max;
        }

        public int getSortIndex()
        {
            return m_index;
        }

        public string getHero(int index)
        {
            if (index >= 0 && index < m_heros.Length)
            {
                return m_heros[index].heroId;
            }

            return "";
        }

        public void setHero(int index, string heroId)
        {
            if (index >= 0 && index < m_heros.Length)
            {
                if (m_heros[index].heroId == heroId)
                {
                    return;
                }
                m_heros[index].heroId = heroId;
                m_heros[index].heroLv = 0;
            }
        }

        public bool hasHero(int index)
        {
            if (index >= 0 && index < m_heros.Length)
            {
                if (!m_heros[index].heroId.empty())
                {
                    return true;
                }
            }

            return false;
        }
        public void clearHeros()
        {
            for (int i = 0; i < 3; ++i)
            {
                if (m_heros[i] == null)
                {
