        public MarchActionType GetMarchType()
        {
            MarchActionType type = MarchActionType.None;

            if (getState() == 0)///没有任何行动
            {
                type = MarchActionType.Home;
            }
            else
            {
                var marchIt = WorldController.getInstance().getMarchInfoByFormationUuid(getUuid());
                if (marchIt == null)///没有行军线信息，可能处于集结中
                {
                    //集结
                    //var cityData = WorldCityController.getInstance().GetWorldCityData(this.);
                    type = MarchActionType.Fight;
                }
                else
                {
                    var queueIt = QueueController.getInstance().getQueueInfoByUuid(marchIt.Uuid);

                    if (marchIt.StateType == MarchStateType.StateMarch)///行军中
                    {
                        if (marchIt.MarchType == MarchMethodType.MethodRally)
                        {
                            type = MarchActionType.InitiateRallyMarch;
                        }
                        else if (marchIt.MarchType == MarchMethodType.MethodUnion)
                        {
                            type = MarchActionType.JoinRally2Home;
                        }
                        else
                        {
                            type = MarchActionType.March;
                        }
                    }
                    else if (marchIt.StateType == MarchStateType.StateReturn)///返回中
                    {
                        type = MarchActionType.Return;
                    }
                    else if (marchIt.StateType == MarchStateType.StateOccupy)
                    {
                        if (marchIt.MarchType == MarchMethodType.MethodRally)
                        {
                            if (marchIt.StartStamp != 0 && marchIt.EndStamp != 0
                                && marchIt.AllianceTeamCreateTime > 0 && marchIt.EndAction == MarchEndAction.MarchActionNone
                                && marchIt.SpeedX == 0 && marchIt.SpeedY == 0)
                            {
                                type = MarchActionType.InitiateRally;
                            }
                            else if (marchIt.TargetType == WorldCityType.tile_one_level_city ||
                                marchIt.TargetType == WorldCityType.tile_one_level_city_range ||
                                marchIt.TargetType == WorldCityType.tile_two_level_city ||
                                marchIt.TargetType == WorldCityType.tile_two_level_city_range ||
                                marchIt.TargetType == WorldCityType.Throne ||
                                marchIt.TargetType == WorldCityType.ThroneRange ||
                                marchIt.TargetType == WorldCityType.Trebuchet ||
                                marchIt.TargetType == WorldCityType.TERRITORY_BANNER ||
                                marchIt.TargetType == WorldCityType.VILLAGE)
                            {
                                /*string json = Newtonsoft.Json.JsonConvert.SerializeObject(marchIt, newtonsoft.Json.JsonSerializerSettings()
                                {
                                    ReferenceLoopHandling = Newtonsoft.Json.ReferenceLoopHandling.Ignore
                                });
                                UnityEngine.Debug.LogWarning(">>> \n" + json);*/

                                type = MarchActionType.Defense;
                            }
                            else if (
                                marchIt.TargetType == WorldCityType.Blood_Area_Big ||
                                marchIt.TargetType == WorldCityType.Blood_Area_Small)
                            {
                                type = MarchActionType.Collect;
                            }

                            else
                            {
                                type = MarchActionType.InitiateRally;
                            }
                        }
                        else if (marchIt.MarchType == MarchMethodType.MethodUnion)
                        {
                            if (!string.IsNullOrEmpty(marchIt.TeamUid))
                            {
                                var initMarchIt = WorldController.getInstance().getMarchInfo(marchIt.TeamUid);
                                if (initMarchIt != null
                                    && initMarchIt.MarchType == MarchMethodType.MethodRally
                                    && initMarchIt.StartStamp != 0 && initMarchIt.EndStamp != 0
                                    && initMarchIt.AllianceTeamCreateTime > 0 && initMarchIt.EndAction == MarchEndAction.MarchActionNone
                                    && initMarchIt.SpeedX == 0 && initMarchIt.SpeedY == 0)
                                {
                                    type = MarchActionType.InitiateRally;
                                }
                                else
                                {
                                    var it = initMarchIt ?? marchIt;
                                    if (it.TargetType == WorldCityType.tile_one_level_city ||
                                        it.TargetType == WorldCityType.tile_one_level_city_range ||
                                        it.TargetType == WorldCityType.tile_two_level_city ||
                                        it.TargetType == WorldCityType.tile_two_level_city_range ||
                                        it.TargetType == WorldCityType.Throne ||
                                        it.TargetType == WorldCityType.ThroneRange ||
                                        it.TargetType == WorldCityType.Trebuchet ||
                                        it.TargetType == WorldCityType.TERRITORY_BANNER ||
                                        it.TargetType == WorldCityType.VILLAGE
    )
                                    {
                                        type = MarchActionType.Defense;
                                    }
                                    else if (
                                        it.TargetType == WorldCityType.Blood_Area_Big ||
                                        it.TargetType == WorldCityType.Blood_Area_Small)
                                    {
                                        type = MarchActionType.Collect;
                                    }
                                    else if (it.StateType == MarchStateType.StateMarch)
                                    {
                                        type = MarchActionType.JoinRallyMarch;
                                    }
                                    else
                                    {
                                        type = MarchActionType.JoinRallyWait;
                                    }
                                }
                            }
                            else
                            {
                                type = MarchActionType.JoinRallyWait;
                            }
                        }
                        else if (marchIt.TargetType == WorldCityType.CampTile)///占领地块
                        {
                            type = MarchActionType.Occupy;
                        }
                        else if (marchIt.TargetType == WorldCityType.ResourceTile ||
                                marchIt.TargetType == WorldCityType.MINE_NEAR_RIVER ||
                                marchIt.TargetType == WorldCityType.MINE_OWN_PLAYER)///采集普通资源、富矿
                        {
                            type = MarchActionType.Collect;
                        }
                        else if (marchIt.TargetType == WorldCityType.Blood_Area_Big ||
                                 marchIt.TargetType == WorldCityType.Blood_Area_Small)///采集血岩矿
                        {
                            type = MarchActionType.Collect;
                        }
                        else if (marchIt.TargetType == WorldCityType.tile_one_level_city ||
                                 marchIt.TargetType == WorldCityType.tile_one_level_city_range ||
                                 marchIt.TargetType == WorldCityType.tile_two_level_city ||
                                 marchIt.TargetType == WorldCityType.tile_two_level_city_range ||
                                 marchIt.TargetType == WorldCityType.Throne ||
                                 marchIt.TargetType == WorldCityType.ThroneRange ||
                                 marchIt.TargetType == WorldCityType.VILLAGE ||
                                 marchIt.TargetType == WorldCityType.TERRITORY_BANNER)
                        {
                            //var cityData = WorldCityController.getInstance().GetWorldCityData(marchIt.EndPointIndex);
                            //if (cityData != null && (cityData.status == CityStatus.OPEND || cityData.status == CityStatus.PROTECTED))
                            //{
                            type = MarchActionType.Defense;
                            //}
                            //else
                            //{
                            //    type = MarchActionType.Occupy;
                            //}
                        }
                        else if (marchIt.TargetType == WorldCityType.CityTile ||
                                 marchIt.TargetType == WorldCityType.CityRange)
                        {
                            type = MarchActionType.Defense;
                        }
                        else if (marchIt.TargetType == WorldCityType.tile_allianceAreaBuild)
                        {
                            type = MarchActionType.Collect;
                        }

                        else
                        {
                            type = MarchActionType.Defense;
                        }
                        if (marchIt.TargetType == WorldCityType.Tile_allianceArea
                            || marchIt.TargetType == WorldCityType.TERRITORY_EXPANSION_BANNER)
                        {
                            if (queueIt.type == (int)QueueType.TYPE_BUILDING_TERRITORY)
                            {
                                type = MarchActionType.TerritoryBuilding;
                            }
                            else if (queueIt.type == (int)QueueType.TYPE_STATION_TERRITORY)
                            {
                                type = MarchActionType.TerritoryDefense;
                            }
                            else if (queueIt.type == (int)QueueType.TYPE_REPAIR_TERRITORY)
                            {
                                type = MarchActionType.TerritoryRepair;
                            }
                            else if (queueIt.type == (int)QueueType.TYPE_DESTROY_TERRITORY)
                            {
                                type = MarchActionType.TerritoryDestory;
                            }
                        }
                    }
                }
            }

            return type;
        }

