        private bool CheckFortOccupyState(MarchInfo marchIt, out string state)
        {
            state = "";
            if (!GlobalData.shared().playerInfo.isInAlliance())
                return false;

            if (marchIt == null)
                return false;

            if (marchIt.StateType == MarchStateType.StateOccupy && marchIt.EndPointIndex > 0)
            {
                var info = AZTerritoryController.getInstance().getTerritoryInfoByPointIndex(marchIt.EndPointIndex);
                if (info != null)
                {
                    switch (info.TerritoryState)
                    {
                        case (int)AAreaState.Astate_Building:
                            state = Global._lang("115305");
                            break;
                        case (int)AAreaState.Astate_Garrison:
                            state = Global._lang("115346");
                            break;
                        case (int)AAreaState.Astate_FixIng:
                            state = Global._lang("115310");
                            break;
                        case (int)AAreaState.Astate_Destroy:
                            state = Global._lang("400004766");
                            break;
                        default:
                            break;
                    }

                    return true;
                }
            }

            return false;
        }

