        }

        public void setLimitForSoldiers(int maxNum)
        {
            maxSoldiers = maxNum;
        }

        public int getSlotArmyMaxCountWithLimit(int solt)
        {
            if (maxSoldiers == -1)
                return getSlotArmyMaxCount(solt);

            int tempNum = maxSoldiers;
            for (int i = 0; i < 3; i++)
            {
                if (i != solt)
                {
                    tempNum -= getSlotArmyCount(i);
                }
            }
            return Global.MIN(getSlotArmyMaxCount(solt), Global.max(0, tempNum));
        }

        public string getUavUid()
        {
            return m_uavUid;
        }
        /// <summary>
        /// 获取上阵的3个英雄heroid
        /// </summary>
        /// <returns></returns>
        /// <exception cref="NotImplementedException"></exception>

        public string[] getHeros()
        {
            return new string[] { m_heros[0].heroId, m_heros[1].heroId, m_heros[2].heroId };
        }
        public List<SuperFormationHeroMarch> getHerosList()
        {
            var m_marchHeros = new List<SuperFormationHeroMarch>();
            for (int i = 0; i < m_heros.Length; i++)
            {
                if (m_heros[i] == null || string.IsNullOrEmpty(m_heros[i].heroId))
                {
                    continue;
                }
                m_marchHeros.Add(m_heros[i]);
            }
            return m_marchHeros;
        }
        public List<SuperFormationSoldierMarch> getSoldierList()
        {
            var m_marchSoldier = new List<SuperFormationSoldierMarch>();
            foreach (var item in m_soldiers.Values)
            {
                foreach (var it in item)
                {
                    if (it.count > 0)
                    {
                        m_marchSoldier.Add(it);
                    }
                }
            }
            return m_marchSoldier;
        }

        public PFrotressInfo get_pFortress()
        {
            return pFortress;
        }

        public void set_pFortress(PFrotressInfo pFrotressInfo)
        {
            pFortress = pFrotressInfo;
        }

        public object getCmdData()
        {
            CCDictionary formDict = new CCDictionary();
            CCArray array_hero = CCArray.create();
            for (int i = 0; i < m_heros.Length; i++)
            {
                if (m_heros[i] == null || string.IsNullOrEmpty(m_heros[i].heroId))
                {
                    continue;
                }
                CCDictionary heroDict = new CCDictionary();
                heroDict.setObject(m_heros[i].heroId, "heroId");
                array_hero.Add(heroDict);
            }

            CCArray array_soldier = CCArray.create();
            foreach (var item in m_soldiers.Values)
            {
                foreach (var it in item)
                {
                    if (it.count > 0)
                    {
                        CCDictionary sodierDict = new CCDictionary();
                        sodierDict.setObject(it.armyId, "armyId");
                        sodierDict.setObject(it.count, "count");
                        array_soldier.Add(sodierDict);
                    }
                }
            }
            CCDictionary drone = new CCDictionary();
            drone.setObject(m_uavUid, "droneUuid");

            formDict.setObject((int)formType, "type");
            formDict.setObject(m_index, "index");
            formDict.setObject(array_hero, "hero");
            formDict.setObject(array_soldier, "soldiers");
            formDict.setObject(drone, "drone");
            formDict.setObject(m_name, "name");
            if (!string.IsNullOrEmpty(miningUid))
            {
                formDict.setObject(miningUid, "miningUid");
            }

            return formDict;
        }
        public void parseHeroSoldierAndUav(CCDictionary dict)
        {
            //Debug.LogError("formation"+dict.ToJson());
            clearHeros();
            clearSoldiers();
            if (dict.ContainsKey("name"))
                m_name = dict.valueForKey("name");
            if (dict.ContainsKey("type"))
                formType = (SuperFormType)dict.valueForKey("type").intValue();
            if (dict.ContainsKey("index"))
                m_index = dict.valueForKey("index").intValue();
            if (dict.ContainsKey("uuid"))
                m_uuid = dict.valueForKey("uuid").getCString();
            CCArray heros = (CCArray)(dict.objectForKey("hero"));
            CCArray.CCARRAY_FOREACH(heros, obj =>
            {
                CCDictionary h = (CCDictionary)(obj);
                if (h != null)
                {
                    string heroId = h.valueForKey("heroId");
                    if (string.IsNullOrEmpty(heroId))
                        return;
                    int starLv = h.valueForKey("starLv").intValue();
                    int heroLv = h.valueForKey("level").intValue();
                    var xmlInfo = FBHeroXMLInfoData.Get(heroId);
                    int index = xmlInfo.icon_type - 1;
                    m_heros[index].heroId = heroId;
                    m_heros[index].heroLv = heroLv;
                    m_heros[index].starLv = starLv;
                    m_heros[index].heroDict = h;
                }
            });
            CCArray soldiers = (CCArray)(dict.objectForKey("soldiers"));
            CCArray.CCARRAY_FOREACH(soldiers, obj =>
            {
                CCDictionary h = (CCDictionary)(obj);
                if (h != null)
                {
                    string armyId = h.valueForKey("armyId");
                    int count = h.valueForKey("count").intValue();
                    int armyType = CCCommonUtils.getArmysInfo(armyId).icon_type;
                    if (!m_soldiers.ContainsKey(armyType) || m_soldiers[armyType] == null)
                        m_soldiers[armyType] = new List<SuperFormationSoldierMarch>();
                    m_soldiers[armyType].Add(new SuperFormationSoldierMarch(armyId, count, h));
                }
            });
            m_uavUid = "";
            if (dict.ContainsKey("drone"))
            {
                uavDict = dict.ObjectForKey("drone") as CCDictionary;
                m_uavUid = uavDict.StringValueForKey("droneUuid");
            }
        }


        public CCArray ToArray()
        {
            var result = new CCArray();
            return result;
        }

        private SuperFormationHeroMarch[] m_herosTemp = new SuperFormationHeroMarch[3];
        private Dictionary<int, List<SuperFormationSoldierMarch>> m_soldiersTemp = new Dictionary<int, List<SuperFormationSoldierMarch>>();
        private string uavUidTemp = "";
        public bool CheckEqual(SuperFormationInfo other)
        {
            m_herosTemp = other.m_heros;
            m_soldiersTemp = other.m_soldiers;
            uavUidTemp = other.m_uavUid;

            return !hasDirtyHerosOrSoldersOrUavs();
            // return true;
        }
        /// <summary>
        /// 检查英雄数据是否发生变更
        /// </summary>
        /// <returns>如果英雄数据发生变更返回true，否则返回false</returns>
        public bool hasDirtyHeros()
        {
            // 检查数组长度是否一致
            if (m_heros.Length != m_herosTemp.Length)
            {
                return true;
            }
            // 逐个比较英雄数据
            for (int i = 0; i < m_heros.Length; i++)
            {
                // 比较英雄ID、军队ID、数量和等级
                if (m_heros[i].heroId != m_herosTemp[i].heroId)
                {
                    return true;
                }
            }
            return false;
        }

        /// <summary>
        /// 检查士兵数据是否发生变更
        /// </summary>
        /// <returns>如果士兵数据发生变更返回true，否则返回false</returns>
        public bool hasDirtySolders()
        {
            // 检查字典键数量是否一致
            if (m_soldiers.Count != m_soldiersTemp.Count)
            {
                return true;
            }

            // 检查每个键对应的士兵列表
            foreach (var kvp in m_soldiers)
            {
                if (!m_soldiersTemp.TryGetValue(kvp.Key, out var tempList))
                {
                    return true;
                }

                var currentList = kvp.Value;
                if (currentList.Count != tempList.Count)
                {
                    return true;
                }

                // 逐个比较士兵数据
                for (int i = 0; i < currentList.Count; i++)
                {
                    if (currentList[i] == null && tempList[i] == null)
                    {
                        continue;
                    }
                    // 比较军队ID和数量
                    if (currentList[i].armyId != tempList[i].armyId ||
                        currentList[i].count != tempList[i].count)
                    {
                        return true;
                    }
                }
            }
            return false;
        }

        /// <summary>
        /// 检查无人机数据是否发生变更
        /// </summary>
        /// <returns>如果无人机数据发生变更返回true，否则返回false</returns>
        public bool hasDirtyUavs()
        {
            // 比较无人机UID
            return m_uavUid != uavUidTemp;
        }

        /// <summary>
        /// 检查英雄、士兵或无人机数据是否发生变更
        /// </summary>
        /// <returns>如果任何一种数据发生变更返回true，否则返回false</returns>
        public bool hasDirtyHerosOrSoldersOrUavs()
        {
            return hasDirtyHeros() || hasDirtySolders() || hasDirtyUavs();
        }

        public bool Empty()
        {
            int soldierCount = 0;
            foreach (var sList in m_soldiers)
            {
                foreach (var s in sList.Value)
                {
                    soldierCount += s.count;
                }
            }
            return soldierCount == 0;
        }

        public long GetPower()
        {
            double result = getATK();

            return Convert.ToInt64(result);
        }
        public string GetFormMsg()
        {
            return $"{Global.SuperFormTypeMsg[(int)formType].Item2} index :{m_index}";
        }
        public string GetFormMsg_log()
        {
            var sb = new System.Text.StringBuilder();
            sb.Append(GetFormMsg());

            var heros = getHerosList();
            sb.Append($" | heros({heros.Count}):");
            for (int i = 0; i < heros.Count; i++)
            {
                var h = heros[i];
                sb.Append($" [{i}]{h.heroId} lv{h.heroLv} star{h.starLv} march{h.maxMarch}");
            }

            var soldiers = getSoldierList();
            sb.Append($" | soldiers({soldiers.Count}):");
            for (int i = 0; i < soldiers.Count; i++)
            {
                var s = soldiers[i];
                sb.Append($" [{i}]{s.armyId}({s.armyType})x{s.count}");
            }

            return sb.ToString();
        }

        internal bool CheckEmpty()
        {
            return !hasHerosOrSolders() && string.IsNullOrEmpty(m_uavUid);
        }
    }
}

