using DragonBones;
namespace DayZ
{
    public class SuperFormationInfo : FormationBaseInfo
    {
        /// <summary>
        /// 队伍类型
        /// </summary>
        public SuperFormType formType = SuperFormType.Default;
        /// <summary>
        /// 队伍序号  从1 开始，和服务器保持一致
        /// </summary>
        private int m_index = 1;
        public int Index
        {
            get
            {
                return m_index;
            }
            set
            {
                m_index = value;
            }
        }
        private string m_name = "";
        public string Name
        {
