            {
                return m_name;
            }
            set
            {
                m_name = value;
            }
        }
        private string m_uuid;
        private int m_state = 0;
        private int m_maxNum = 0;
        /// <summary>
        /// 英雄
        /// 补兵、骑兵、弓兵
        /// 0\1\2
        /// </summary>
        public SuperFormationHeroMarch[] m_heros = new SuperFormationHeroMarch[3];
        /// <summary>
        /// 士兵
        /// key：补兵、骑兵、弓兵Arms.json 》arms_type 1\2\3
        /// value：T1-T10
        /// </summary>
        public Dictionary<int, List<SuperFormationSoldierMarch>> m_soldiers = new Dictionary<int, List<SuperFormationSoldierMarch>>();
        public CCDictionary uavDict;
        private string m_uavUid = "";
        public string uavUid
        {
            get { return m_uavUid; }
            set { m_uavUid = value; }
        }

        public string miningUid { get; set; }
        public string uav_uuid
        {
            get
            {
                return uavUid;
            }
        }

        public int maxSoldiers = -1;

        /// <summary>
        /// 设置无人机UID
        /// </summary>
        /// <param name="uavUid">无人机UID</param>
        public void setUavUid(string uavUid)
        {
            if (m_uavUid == uavUid)
                return;

            m_uavUid = uavUid;
        }

        /// <summary>
        /// 清除无人机数据
        /// </summary>
        public void clearUav()
        {
            if (!string.IsNullOrEmpty(m_uavUid))
            {
                m_uavUid = "";
            }
        }
        protected int m_resType;
        public int getResType() { return m_resType; }
        public void setResType(int var) { m_resType = var; }
        public PFrotressInfo pFortress = new PFrotressInfo();
        public List<SuperFormationAttrInfo> formationAttrInfo = new List<SuperFormationAttrInfo>() { new SuperFormationAttrInfo(), new SuperFormationAttrInfo(), new SuperFormationAttrInfo() };

        public static SuperFormationInfo create()
        {
            return new SuperFormationInfo();
        }
        private SuperFormationInfo()
        {
            this.m_index = 1;
            this.m_resType = 0;
            for (int i = 0; i < m_heros.Length; i++)
            {
                if (m_heros[i] == null)
                {
                    m_heros[i] = new SuperFormationHeroMarch();
                }
            }
        }
        public SuperFormationInfo(CCDictionary dict)
        {
            initFromDict(dict);
        }

        public void assignTo(SuperFormationInfo infoDest)
        {
            infoDest.formType = formType;
            infoDest.m_index = m_index;
            infoDest.m_state = m_state;
            infoDest.Name = m_name;
            infoDest.m_maxNum = m_maxNum;
            for (int i = 0; i < Global._countof(m_heros); ++i)
            {
                infoDest.m_heros[i] = new SuperFormationHeroMarch();
                infoDest.m_heros[i].heroId = m_heros[i].heroId;
                infoDest.m_heros[i].maxMarch = m_heros[i].maxMarch;
                infoDest.m_heros[i].heroLv = m_heros[i].heroLv;
                infoDest.m_heros[i].heroDict = m_heros[i].heroDict;
            }
            infoDest.m_soldiers.Clear();
            foreach (var soldier in m_soldiers)
            {

                //SuperFormationSoldierMarch []soldierList = new SuperFormationSoldierMarch[soldier.Value.Count];//SuperFormationSoldierMarch>();
                // soldier.Value.CopyTo(soldierList);
                var marchList = new List<SuperFormationSoldierMarch>();
                foreach (var march in soldier.Value)
                {
                    marchList.Add(new SuperFormationSoldierMarch(march.armyId, march.count, march.info_dict));
                }
                infoDest.m_soldiers.Add(soldier.Key, marchList);
            }
            infoDest.setUavUid(m_uavUid);
        }
        public SuperFormationInfo CopyTo()
        {
            SuperFormationInfo info = new SuperFormationInfo();
            info.formType = formType;
            info.m_index = m_index;
            info.m_state = m_state;
            info.Name = m_name;
            info.m_maxNum = m_maxNum;
            for (int i = 0; i < Global._countof(m_heros); ++i)
            {
                info.m_heros[i] = new SuperFormationHeroMarch();
                info.m_heros[i].heroId = m_heros[i].heroId;
                info.m_heros[i].maxMarch = m_heros[i].maxMarch;
                info.m_heros[i].heroLv = m_heros[i].heroLv;
                info.m_heros[i].heroDict = m_heros[i].heroDict;
            }
            info.m_soldiers.Clear();
            foreach (var soldier in m_soldiers)
            {
                var marchList = new List<SuperFormationSoldierMarch>();
                foreach (var march in soldier.Value)
                {
                    marchList.Add(new SuperFormationSoldierMarch(march.armyId, march.count, march.info_dict));
                }
                info.m_soldiers.Add(soldier.Key, marchList);
            }
            info.setUavUid(m_uavUid);
            return info;
        }


        public bool initFromDict(CCDictionary dict)
        {
            if (dict == null)
            {
                return false;
            }
            parseHeroSoldierAndUav(dict);
            if (dict.ContainsKey("maxNum"))
            {
                m_maxNum = (int)dict.valueForKey("maxNum").longValue();
                LogCommon.LogError($"SuperFormationInfo initFromDict maxNum: {m_maxNum}");
            }

            CCDictionary dic = (CCDictionary)(dict.objectForKey("march"));
            if (dic != null)
            {
                if (dic.objectForKey("uuid") != null)
                {
                    CollectInfo resInfo = CollectInfo.create();

                    string key = dic.valueForKey("uuid");
                    resInfo.troopMax = dic.valueForKey("q").intValue();
                    resInfo.digSpeed = dic.valueForKey("spd").floatValue();
                    resInfo.digStartTime = dic.valueForKey("sdt").doubleValue();
                    resInfo.digStartNum = dic.valueForKey("collected").intValue();
                    resInfo.changeCollectSpdTime = dic.valueForKey("changeCollectSpdTime").doubleValue();
                    resInfo.resType = dic.valueForKey("t").intValue();
                    m_ResCollect[key] = resInfo;
                }
            }

            CCDictionary pfortressDic = (CCDictionary)(dict.objectForKey("world_building"));
            if (pfortressDic != null)
            {
                pFortress.pointId = pfortressDic.valueForKey("pointId").intValue();
                pFortress.index = pfortressDic.valueForKey("index").intValue();
            }
            refreshFromData();

            return true;
        }

        void refreshFromData()
        {
            for (int slot = 0; slot < 3; slot++)
            {
                formationAttrInfo[slot].refreshData(this, slot);
            }
        }
        double getFormPower()
        {
            double power = 0;
            for (int slot = 0; slot < 3; slot++)
            {
                if (formationAttrInfo[slot] != null)
                {
                    //power += formationAttrInfo[slot].GetPowerWithSoldier();
                    var fi = formationAttrInfo[slot];
                    // fi.soliderNum = Math.Max(fi.soliderMaxNum, fi.soliderNum);
                    power += PackMgr.GetFormSlotPower(fi);
                    //LogCommon.LogError($"getFormPower:{fi._armyId} - {fi.soliderNum}");
                }
            }
            return power;
        }
        /// <summary>
        /// 当前阵容的最大战力，不考虑实际兵够不够
        /// </summary>
        /// <returns></returns>
        double getFormMaxPower()
        {
            double power = 0;
            for (int slot = 0; slot < 3; slot++)
            {
                if (formationAttrInfo[slot] != null)
                {
                    var fi = formationAttrInfo[slot];
                    power += PackMgr.GetFormSlotPower(fi);
                    // LogCommon.LogError($"队伍{fi._armyId}--{fi.soliderMaxNum}--");
                }
            }
            return power;
        }
        public int GetTroopAddRateByArmyCount(int current, int max)
        {
            return getTroopAddRateByArmyCount(current, max);
        }
        private int getTroopAddRateByArmyCount(int current, int max)
        {
            var rate = 100.0f * current / max;
            var dict = DataAtlasManager.Instance.GetDataWithType<New_hero_upgrade>();
            using (var itor = dict.GetEnumerator())
            {
                while (itor.MoveNext())
                {
                    var child = itor.Current.Value as New_hero_upgrade;
                    if (rate >= child.min && rate < child.max)
                    {
#if UNITY_EDITOR
                        //                LogCommon.LogError("英雄兵力系数>> current:{0} ; max:{1} ; Rate :{2}", current, max, child.proportion);
#endif
                        return child.proportion;
                    }
                }
            }
#if UNITY_EDITOR
            //  LogCommon.LogError("英雄兵力系数>> current:{0} ; max:{1} ; Rate :{2}", current, max, 100);
#endif
            return 100;
        }



        public string getUuid()
