        {
            var sb = new System.Text.StringBuilder();
            sb.AppendLine($"\n========== 阵容信息 {GetFormMsg()} ==========");

            var heros = getHerosList();
            sb.AppendLine($"【英雄】共 {heros.Count} 名");
            for (int i = 0; i < heros.Count; i++)
            {
                var h = heros[i];
                sb.AppendLine($"  英雄{i + 1}: {h.heroId} | 等级:{h.heroLv} | 星级:{h.starLv} | 带兵量:{h.maxMarch}");
            }

            var soldiers = getSoldierList();
            sb.AppendLine($"【士兵】共 {soldiers.Count} 种");
            int totalSoldier = 0;
            for (int i = 0; i < soldiers.Count; i++)
            {
                var s = soldiers[i];
                totalSoldier += s.count;
                sb.AppendLine($"  兵种{i + 1}: {s.armyType}({s.armyId}) | 数量:{s.count}");
            }
            sb.AppendLine($"  士兵总数: {totalSoldier}");
            sb.Append("===========================================");

            return sb.ToString();
        }

        internal bool CheckEmpty()
        {
            return !hasHerosOrSolders() && string.IsNullOrEmpty(m_uavUid);
        }
    }
